<style>
:root{--canvas:#fbf9f5;--ink:#1b2520;--muted:#717e77;--brand:#1e4b38;--accent:#c86d51;--line:#e5dfd5;--surface:#f8f6f2}*{box-sizing:border-box}body{margin:0;min-height:100vh;background:var(--canvas);color:var(--ink);font-family:'Plus Jakarta Sans',sans-serif;padding:24px}a{color:inherit;text-decoration:none}.shell{width:min(1160px,100%);margin:auto;display:grid;grid-template-columns:330px 1fr;background:#fff;border:1px solid var(--line);border-radius:20px;overflow:hidden;box-shadow:0 20px 48px -8px rgba(27,37,32,.14)}.aside{padding:38px 32px;display:flex;flex-direction:column;justify-content:space-between;background:linear-gradient(160deg,#e7f2e9,#f4eee8)}.brand{display:flex;align-items:center;gap:10px;color:var(--brand);font-weight:800}.brand img{width:34px;height:34px}.aside-content{margin:auto 0}.eyebrow{color:var(--accent);font-size:11px;font-weight:800;letter-spacing:.12em;text-transform:uppercase}.aside h1{font:600 48px/1 'EB Garamond',serif;margin:12px 0}.aside p,.form-heading p{color:var(--muted);font-size:13px;line-height:1.7}.aside-note{padding-top:20px;border-top:1px solid rgba(30,75,56,.16);color:var(--muted);font-size:11px;line-height:1.6}.form-panel{padding:clamp(28px,5vw,56px)}.form-heading{margin-bottom:24px}.form-heading h2{font:600 36px/1.05 'EB Garamond',serif;margin:8px 0}.form-heading p{font-size:12px;margin:0}.form-grid{display:grid;grid-template-columns:1fr 1fr;gap:14px 16px}.field label{display:block;margin-bottom:7px;font-size:11px;font-weight:800}.field input,.field select{width:100%;min-height:44px;padding:10px 12px;border:1px solid var(--line);border-radius:8px;background:var(--surface);font:12px 'Plus Jakarta Sans'}.field input:focus,.field select:focus{outline:0;border-color:var(--brand);box-shadow:0 0 0 3px rgba(30,75,56,.12)}.field small{display:block;margin-top:5px;color:var(--muted);font-size:10px}.full{grid-column:1/-1}.error{margin-top:5px;color:#a53c27;font-size:10px}.alert{padding:11px 13px;margin-bottom:18px;border-radius:8px;background:#ffebe6;color:#8b351f;font-size:12px}.alert ul{margin:0;padding-left:18px}.btn{display:flex;justify-content:center;align-items:center;width:100%;min-height:46px;border:1px solid var(--brand);border-radius:8px;background:var(--brand);color:#fff;font:700 13px 'Plus Jakarta Sans';cursor:pointer}.footer{text-align:center;margin-top:20px;color:var(--muted);font-size:12px}.footer a{color:var(--brand);font-weight:800}@media(max-width:840px){body{padding:12px}.shell{grid-template-columns:1fr}.aside{min-height:210px;padding:26px 24px}.aside-content{margin:36px 0 0}.aside h1{font-size:38px}.aside-note{display:none}.form-panel{padding:28px 22px}}@media(max-width:560px){.form-grid{grid-template-columns:1fr}.full{grid-column:auto}.form-heading h2{font-size:32px}}
</style></head>
<body><main class="shell"><aside class="aside"><a class="brand" href="{{ route('customer.dashboard') }}"><img src="{{ asset('assets/logo/logo.png') }}" alt="EcoCraft"><span>EcoCraft</span></a><div class="aside-content"><div class="eyebrow">Seller Center</div><h1>Jual dengan makna.</h1><p>Bawa karya lokal dan material berkelanjutanmu ke komunitas yang memilih dengan sadar.</p></div><div class="aside-note">Setelah pendaftaran dikirim, admin akan memeriksa data dan dokumenmu sebelum akun seller diaktifkan.</div></aside><section class="form-panel"><div class="form-heading"><div class="eyebrow">Pendaftaran seller</div><h2>Mulai toko berkelanjutanmu.</h2><p>Lengkapi data di bawah ini. Semua field wajib diisi untuk proses verifikasi.</p></div>@if($errors->any())<div class="alert"><ul>@foreach($errors->all() as $error)<li>{{ $error }}</li>@endforeach</ul></div>@endif<form method="POST" action="{{ route('seller.register.submit') }}" enctype="multipart/form-data"><div class="form-grid">@csrf
<div class="field"><label for="name_sellers">Nama seller</label><input id="name_sellers" name="name_sellers" value="{{ old('name_sellers') }}" required>@error('name_sellers')<div class="error">{{ $message }}</div>@enderror</div><div class="field"><label for="store_name">Nama toko</label><input id="store_name" name="store_name" value="{{ old('store_name') }}" required>@error('store_name')<div class="error">{{ $message }}</div>@enderror</div><div class="field"><label for="email">Email seller</label><input id="email" type="email" name="email" value="{{ old('email') }}" required>@error('email')<div class="error">{{ $message }}</div>@enderror</div><div class="field"><label for="phone_number">Nomor WhatsApp</label><input id="phone_number" name="phone_number" value="{{ old('phone_number') }}" required>@error('phone_number')<div class="error">{{ $message }}</div>@enderror</div><div class="field"><label for="gender">Jenis kelamin</label><select id="gender" name="gender" required><option value="">Pilih jenis kelamin</option><option value="male" @selected(old('gender')==='male')>Laki-laki</option><option value="female" @selected(old('gender')==='female')>Perempuan</option><option value="other" @selected(old('gender')==='other')>Lainnya</option></select></div><div class="field"><label for="province">Provinsi</label><select id="province" name="province" required><option value="">Pilih provinsi</option></select></div><div class="field"><label for="city">Kota</label><select id="city" name="city" required disabled><option value="">Pilih provinsi terlebih dahulu</option></select></div><div class="field full"><label for="address">Alamat lengkap</label><input id="address" name="address" value="{{ old('address') }}" required></div><div class="field"><label for="password">Kata sandi</label><input id="password" type="password" name="password" required><small>Minimal 9 karakter.</small></div><div class="field"><label for="password_confirmation">Konfirmasi kata sandi</label><input id="password_confirmation" type="password" name="password_confirmation" required></div><div class="field full"><label for="ktp_image">Foto KTP</label><input id="ktp_image" type="file" name="ktp_image" accept="image/jpeg,image/png" required><small>JPG atau PNG, maksimal 2 MB.</small></div><div class="full"><button class="btn" type="submit">Ajukan pendaftaran seller</button></div></div></form><div class="footer">Sudah punya akun seller? <a href="{{ route('seller.login') }}">Masuk sebagai seller</a></div></section></main>
<script>const data={"DKI Jakarta":["Jakarta Barat","Jakarta Pusat","Jakarta Selatan","Jakarta Timur","Jakarta Utara"],"Jawa Barat":["Bandung","Bekasi","Bogor","Cimahi","Cirebon","Depok","Sukabumi","Tasikmalaya"],"Jawa Tengah":["Semarang","Magelang","Pekalongan","Salatiga","Surakarta","Tegal"],"Jawa Timur":["Batu","Blitar","Kediri","Malang","Mojokerto","Pasuruan","Probolinggo","Surabaya"],"Banten":["Cilegon","Serang","Tangerang","Tangerang Selatan"],"Bali":["Denpasar","Singaraja"],"Sumatera Utara":["Medan","Binjai","Pematangsiantar"],"Sumatera Barat":["Padang","Bukittinggi","Payakumbuh"],"Riau":["Pekanbaru","Dumai"],"Kalimantan Timur":["Balikpapan","Bontang","Samarinda"],"Sulawesi Selatan":["Makassar","Palopo","Parepare"],"Papua":["Jayapura"]};const p=document.getElementById('province'),c=document.getElementById('city');Object.keys(data).forEach(x=>p.add(new Option(x,x)));function cities(name,selected=''){c.innerHTML='<option value="">Pilih kota</option>';(data[name]||[]).forEach(x=>c.add(new Option(x,x,false,x===selected)));c.disabled=!data[name]}p.onchange=()=>cities(p.value);const oldP=@json(old('province')),oldC=@json(old('city'));if(oldP){p.value=oldP;cities(oldP,oldC)}</script></body></html>
